import pathlib,json,re,hashlib
R=pathlib.Path.cwd();D='2026-11-08'
over=json.loads((R/'src/data/i18n/en-overrides.json').read_text(encoding='utf-8-sig'))
reviews=json.loads((R/'docs/editorial/news-reviews.json').read_text(encoding='utf-8-sig'));items=[]
def article(slug,title,en,desc,den,pairs,sources,photo,review):
 p=R/f'src/pages/news/{slug}.md';fm=re.split(r'^---\s*$',p.read_text(encoding='utf8'),flags=re.M)[1].split('sources:')[0].strip()
 for k,z,e in [('title',title,en),('description',desc,den)]:
  fm=re.sub(r'^'+k+r':.*$',k+': '+json.dumps(z,ensure_ascii=False),fm,flags=re.M);over[z]=e
 over[title+'｜環球教育新聞網 Global Education News']=en+' | Global Education News'
 for k,v in photo.items():fm=re.sub(r'^'+k+r':.*$',k+': '+json.dumps(v,ensure_ascii=False),fm,flags=re.M)
 fm=re.sub(r'^updated:.*\n?','',fm,flags=re.M).strip()+'\nupdated: "2026-11-08T05:52:00+08:00"\nsources: '+json.dumps([dict(label=l,url=u) for l,u in sources],ensure_ascii=False)
 for z,e in pairs:over[z]=e
 method='本文於11月8日實質修訂，保留原發布日；重新對照官方文件與獨立報導。未進行額外訪談，學生決策建議為編輯分析，公開資料的日期與適用範圍分別標明。'
 over[method]='Substantively revised on November 8 while preserving the original publication date. We rechecked official documents and independent reporting. No additional interviews were conducted. Student decision guidance is editorial analysis; dates and scope of public evidence are identified separately.'
 raw='\n\n'+'\n\n'.join(z for z,e in pairs)+'\n\n## 資料與報導方法\n\n'+method+'\n'
 p.write_text('---\n'+fm+'\n---'+raw,encoding='utf8')
 checked=re.split(r'^---\s*$',p.read_text(encoding='utf8'),flags=re.M)[2]
 review.update(primarySource=sources[0][1],independentSource=sources[1][1],reviewedAt=D,bodySha256=hashlib.sha256(checked.encode()).hexdigest());reviews[slug]=review
 items.append(dict(slug=slug,path=p.relative_to(R).as_posix(),url=f'https://globalednews.com/news/{slug}/',sources=sources,bodyCjk=len(re.findall('[\u3400-\u9fff]',''.join(z for z,e in pairs)))))

article('us-cpt-lawsuit-court-status-october-13-2026','美國CPT訴訟聽證後待裁：聲請暫停，不等於已獲准實習','US CPT lawsuit awaits a decision after hearing: seeking a stay is not work authorization','11月6日法院聽取初步禁制令與暫停聲請，公開案卷記載交付審酌；本次補足訴訟進展、課程爭議與學生應確認的授權界線。','The November 6 docket records a hearing followed by consideration of the requested preliminary relief. This revision distinguishes litigation progress, curricular disputes and individual authorization.',[
('美國大學團體挑戰CPT解釋的訴訟，已從10月提告進入11月聽證。麻州聯邦地方法院公開案卷記載，法官於11月6日聽取初步禁制令與暫停聲請的辯論，並將事項交付審酌。這項紀錄說明法院已聽取雙方意見，並不等於已准許聲請、撤銷爭議指引，或替任何學生發出實習授權。本文因此更新程序狀態，保留10月13日的原發布日期。','The CPT challenge has moved from an October filing to a November hearing. The public Massachusetts district court docket records argument on preliminary relief on November 6, followed by the matter being taken under advisement. That entry is not an order granting relief, withdrawing guidance or authorizing an individual internship. This revision preserves the original October 13 publication date.'),
('爭議源自SEVP於8月12日及24日發布的訊息。AAU與另外三個高教團體10月5日提告，主張政府將CPT中的課程要求解釋得過於狹窄，並爭執行政程序。AAU是原告之一，其公告可確認提告日期與自身主張，但不是中立裁判。報導必須把團體認為政策違法、政府如何回應與法官最後如何裁定分開，不能只因訴狀寫得具體就把指控當成司法認定。','AAU and three other higher-education associations filed on October 5 over SEVP messages dated August 12 and 24. They challenge a restrictive interpretation of curricular requirements and the administrative process. AAU’s announcement establishes its filing and position, not a neutral legal finding. The allegations, the government’s response and a court decision must remain distinct.'),
('獨立媒體Inside Higher Ed於10月8日報導，爭議核心在於實習是否必須是所有同學畢業的共同要求，或可透過選修、學分與課程設計成為教育的一部分。報導描述部分學校因此暫停或調整實習安排。這提供了制度在校園如何發生影響的外部觀察，卻不能推論全美所有學校採用相同做法，也不能把受訪校園的處理方式直接套到台灣學生自己的學位課程。','Inside Higher Ed’s October 8 reporting examines whether training must be compulsory for all students to graduate, rather than integrated through electives, credit or curriculum design. It reports institutional pauses and adjustments. These observations illustrate consequences on campuses, but do not establish a uniform national response or the rule applicable to a Taiwanese student’s own programme.'),
('本次查閱的案號為1:26-cv-14520，承審法官是Julia E. Kobick。案卷依序列出10月28日政府反對文件、11月4日原告回覆，以及11月6日聽證紀錄。公開RECAP資料可能晚於法院正式系統更新，因此本刊只描述已實際讀到的最新條目，不宣稱未出現在鏡像中的文件必定不存在。後續是否發布書面命令及其範圍，仍須以法院正式文件確認。','Case 1:26-cv-14520 is before Judge Julia E. Kobick. The inspected docket lists the government’s October 28 opposition, the plaintiffs’ November 4 reply and the November 6 hearing. RECAP may lag the court’s official system. We describe the latest entry actually inspected rather than claiming that an absent mirrored document cannot exist; any subsequent written order and its scope need confirmation.'),
('對正在安排海外實習的家庭，編輯建議先把問題分成課程、校方與工作三層。課程手冊如何定義這段實習、學校國際學生單位如何處理授權、雇主預計何時開始工作，三者需要能互相對應。只拿到雇主邀請或教授口頭同意，尚不足以回答移民授權問題；同樣地，看到另一所大學仍提供實習，也不能證明自己的課程可以照辦。這是資訊核對方法，不是替個案判定合法性的意見。','Our editorial recommendation is to align three records: the programme’s curricular requirements, the international office’s authorization process and the employer’s proposed start date. An invitation or a professor’s verbal approval does not answer the authorization question. Another university’s continuing placement programme does not establish the answer for one’s own degree. This is a method for checking information, not an individual legal determination.'),
('選校階段也應把「課程包含實習」拆成更具體的問題：是否必修、是否計入學分、何時申請、由誰確認資格，以及無法完成時有何替代課程。學校宣傳的就業成果，與特定學生能否在指定日期開始訓練，是不同證據。若家庭把實習收入列入留學預算，更需要為等待審查或改走非實習路徑保留空間，避免先承擔住宿與交通支出，才發現必要文件尚未完成。','At school-selection stage, ask whether a placement is compulsory, credit-bearing and subject to a separate authorization timeline, and what academic alternative exists. Employment outcomes in marketing materials do not establish permission for a particular student to start on a particular date. A budget that depends on internship earnings should allow for delays or an academic route without placement before committing to accommodation and travel.'),
('這起案件談的是CPT，不能將其程序進展概括成所有F-1工作安排都已改變。不同類型實務訓練、在學工作與畢業後規劃有不同條件；網路討論若只留下「美國實習恢復」幾個字，便刪除了最重要的制度範圍。學生向指定校方人員詢問時，應清楚交代課程、實習性質與目前文件階段，並保留書面答覆；若已收到個別通知，也不應以一般新聞取代該通知的處理要求。','A CPT case should not be generalized to every F-1 employment arrangement. Practical-training categories, work during study and post-graduation plans involve different conditions. A headline saying US internships have resumed would erase the issue’s scope. Students should identify the programme, placement and document stage when seeking a written institutional response; a general news article cannot replace an individual notice.'),
('下一個值得追蹤的訊號，是法院書面命令，而不是只有訴訟雙方對聽證的評論。即使日後出現暫時救濟，仍須閱讀適用對象、期限與具體措辭，不能把程序上的暫時安排寫成終局勝訴。本次修訂也更換舊文誤用的加拿大校園圖片，改為清楚標示的美國賓州州立大學資料照；圖片只提供校園背景，不表示該校是本案個別當事人或照片拍於聽證現場。','The next meaningful signal is a written court order, not merely either side’s account of the hearing. Any interim relief would require attention to beneficiaries, duration and wording, rather than being described as a final victory. We also replace the old article’s incorrectly identified Canadian campus image with a labelled Penn State archive photograph. It supplies US campus context, not evidence that the institution is an individual party or that the image depicts the hearing.')],
[('AAU — filing and plaintiffs’ position','https://www.aau.edu/resource-library/aau-files-lawsuit-challenging-changes-to-the-curricular-practical-training-cpt-program-for-international-students'),('Inside Higher Ed — independent reporting, October 8','https://www.insidehighered.com/news/students/careers/2026/10/08/higher-ed-groups-fight-intl-student-internship-restrictions'),('CourtListener RECAP — docket and November 6 minute entry','https://www.courtlistener.com/docket/74919449/association-of-american-universities-v-us-department-of-homeland/'),('Presidents’ Alliance — litigation documents and chronology','https://www.presidentsalliance.org/cpt-litigation/')],
dict(image='/images/daily/2026-11-07/us.jpg',imageAlt='美國賓州州立大學Old Main資料照，非本案聽證現場',imageCredit='Penn State iGEM 2008 / Public domain；資料照',imageSource='https://commons.wikimedia.org/wiki/File:Old_Main_-_Penn_State.png'),
dict(newsValue='將10月提告進展更新至11月6日聽證後交付審酌，避免把聲請救濟誤報為已獲准或終局勝訴。',background='說明8月SEVP訊息與課程必修、選修訓練之爭議，區分團體主張與正式法律裁判。',development='逐項核對政府反對、原告回覆與聽證日期，揭露RECAP更新延遲而不宣稱鏡像完整即時。',perspectives='以原告公告、獨立高教媒體及法院程序紀錄並列，各自僅支持其可確認的事實範圍。',taiwanImpact='把台灣學生決策連到課程要求、校方授權、雇主起日與預算替代安排，不保證個別工作資格。',uncertainty='尚未從實查最新案卷看到准許救濟的命令；公開鏡像可能延遲，後續命令與範圍須再核對。',independence='Inside Higher Ed為獨立採訪媒體，提供校園影響而非僅轉載原告；CourtListener提供法院案卷條目。'))

article('uk-universities-tighten-international-offers-visa-compliance-2026','英國學生贊助合規分階段收緊：完成率90%要到2027年','UK student-sponsor compliance tightens in stages: 90% completion applies from 2027','重新對照UKVI合規指引，修正完成率門檻的生效年；拒簽率、入學率與學校CAS審查不能當成個人拒簽預測。','A recheck of UKVI guidance corrects the effective year of the completion threshold and separates institutional metrics from an applicant’s individual visa outcome.',[
('英國提高學生贊助機構合規要求的政策，不能把三項門檻全部寫成同一天生效。UKVI現行合規指引明列：自2026年6月1日起，簽證拒簽率須低於5%，入學率至少95%，但課程完成率仍至少85%；完成率提高至90%是2027年6月1日起。本次修訂更正原稿的時間簡化，讓台灣學生能區分今年已適用的要求與下一階段的調整。','UKVI’s compliance guidance phases the thresholds. From June 1, 2026, refusals must be below 5% and enrolment at least 95%, while completion remains at least 85%. The 90% completion requirement applies from June 1, 2027. This revision corrects the earlier article’s compressed timeline rather than treating every threshold as effective on the same day.'),
('政府6月4日新聞稿以加強大學責任說明改革方向，但新聞稿的政策概述不等於逐條操作指引。查閱時也要注意文件網頁11月6日的更新紀錄，主要涉及新增無障礙版本，不能因此推論當天又提高一次合規門檻。學校如何接受評估，應回到適用期間與正式條文；對讀者而言，最有用的不是記住一個最新網頁日期，而是知道該數字對應哪一輪評估。','The government’s June 4 release outlines stronger institutional accountability; operational guidance supplies the phased detail. The November 6 publication update concerns accessible versions and does not establish another threshold increase that day. Readers need the assessment period attached to a number, rather than assuming a webpage’s latest date is the commencement date of every rule on it.'),
('這三項比例衡量的是贊助機構的整體表現，不是每名學生自己的成功機率。拒簽率、取得許可後是否入學，以及完成課程的學生比例，涉及不同群體與階段。若只看某校一項數字，便推論台灣學生一定容易或難以申請，會跳過課程、資格與個案文件的重要差異。紅黃綠評級中的綠色標準，也不能與最低合規門檻混為一談，兩者回答的問題不同。','These are institutional measures, not an individual’s probability of success. Refusals, subsequent enrolment and course completion concern different populations and stages. One institutional figure cannot predict a Taiwanese applicant’s outcome without considering the programme and documents. Green-band criteria in the rating framework should also be distinguished from the minimum compliance thresholds.'),
('ICEF Monitor在5月27日的獨立分析指出，英國第一季學生簽證核發下滑，拒簽壓力在不同生源市場並不平均，學校對更低拒簽率門檻的準備可能影響招生活動。這份報導早於6月實施，適合解釋政策背景與業界擔憂，不能用來證明改革後所有大學都已減少錄取。報導提到的特定市場風險，也不能不加區別地轉成對台灣申請人的判斷。','ICEF Monitor’s independent May 27 analysis describes declining first-quarter study-visa grants, uneven refusal pressures across source markets and recruitment concerns surrounding the lower refusal threshold. It predates June implementation, so it provides context and sector expectations rather than proof of universal subsequent offer cuts. Market-specific observations cannot simply be transferred to Taiwanese applicants.'),
('對家庭最直接的影響，是申請流程中可能需要更早準備完整資料，但「可能加強審查」仍不等於每校一律撤回錄取。編輯建議分別記下學術錄取條件、校方發出CAS前的文件要求與簽證送件時程。如果學校追加文件，先請對方說明是哪個環節、何時需要，以及未能及時提供的處理方式，才能判斷是否影響住宿與機票安排，而非從新聞標題猜測學校的下一步。','Families can prepare by recording offer conditions, the university’s pre-CAS document requirements and the visa timetable separately. Additional scrutiny does not mean every institution withdraws offers. If documents are requested, ask which stage they concern, when they are due and what happens if they are late before changing accommodation or travel plans. A headline cannot supply the university’s actual next step.'),
('財力證明、學歷與語言資料的準備，應以當期官方要求及校方書面清單為依據，不是因新聞提到合規就自行增加無關文件。資料越多不一定越清楚；真正重要的是姓名、課程、時間與金額能否互相一致，以及過期或不完整資料能否及時補正。這些是申請管理上的建議，不代表提供某一份文件即可保證CAS或簽證，也不替任何學生判斷是否符合全部移民條件。','Use current official requirements and the university’s written checklist for financial, academic and language evidence. More documents are not automatically better; consistency of names, programme, dates and amounts, and timely correction of incomplete material, are more useful. These are application-management recommendations, not guarantees that a document will secure a CAS or visa or a finding that a student meets every immigration condition.'),
('已拿到錄取的人，還應確認不同承諾由誰負責。招生部門決定學術錄取，贊助相關單位處理CAS，主管機關則決定簽證；其中一項進展不能替代其他步驟。若校方說明政策正在調整，可以要求對應自己的入學年度與課程，而不是只接受一封泛稱所有國際生的通知。對已付訂金的家庭，退款與延後入學也應查原契約，不能由合規新聞直接推導出新權利。','An offer holder should identify which office is responsible for each commitment: admission, sponsorship documentation and the government’s visa decision are different steps. Ask for explanations tied to the intended intake and programme when institutional procedures change. Deposits, refunds and deferral depend on the relevant terms; a compliance news story does not itself create a new contractual entitlement.'),
('接下來值得追蹤的是2027完成率門檻準備、機構正式通知及有清楚期間的評估結果。本文不以未公開或未實查的評級替任何大學排名，也不宣稱台灣國籍被列為普遍高風險。修訂的目的，是把官方門檻、媒體觀察與家庭決策放回各自證據範圍。配圖為伯明罕城市大學校園資料照，只提供英國高教背景，不暗示該校不合規、受到處分或已撤回任何特定錄取。','Next signals include preparation for the 2027 completion threshold, formal institutional notices and assessments with clear reference periods. We do not rank universities using unverified ratings or label Taiwanese nationality universally high risk. The Birmingham City University archive photograph provides UK higher-education context; it does not imply non-compliance, sanctions or withdrawal of a particular offer.')],
[('UKVI — operational compliance guidance and phased thresholds','https://www.gov.uk/government/publications/student-sponsor-guidance/student-sponsor-compliance-accessible'),('ICEF Monitor — independent analysis, May 27','https://monitor.icef.com/2026/05/uk-sponsored-study-visa-issuances-down-rejection-rates-up-and-more/'),('Home Office — June 4 policy announcement','https://www.gov.uk/government/news/universities-face-ban-on-international-students-over-visa-abuse'),('UKVI — publication revision history','https://www.gov.uk/government/publications/student-sponsor-guidance')],
dict(image='/images/daily/2026-11-07/uk.jpg',imageAlt='伯明罕城市大學校園資料照，不代表合規處分',imageCredit='N Chadwick / CC BY-SA 2.0；資料照',imageSource='https://commons.wikimedia.org/wiki/File:Birmingham_City_University_-_geograph.org.uk_-_4648027.jpg'),
dict(newsValue='修正原文完成率90%生效時間，明確分開2026拒簽與入學門檻、2027完成率新要求。',background='交代機構合規三項指標與個人申請不同，並區分新聞稿、操作指引及無障礙版本更新日期。',development='依正式指引核對分年時間，不把5月的市場觀察當成6月實施後已發生的全面收緊結果。',perspectives='政策目的與ICEF獨立業界分析分別歸屬，指出市場差異與分析時間，避免單一政府視角。',taiwanImpact='以錄取、CAS、簽證三步驟連結文件、訂金與出發安排，不把整體比例當台灣學生成功率。',uncertainty='不替任何學校評定風險或聲稱撤回錄取，不保證提供文件即核准，契約權利須個別確認。',independence='ICEF Monitor提供獨立教育市場分析而非政府公告轉載，且明示資料早於政策實施的限制。'))

article('australia-international-student-demand-below-allocations-2026','澳洲招生規劃與實際入學落差：先分清新生、在校生與校方目標','Australia’s recruitment gap: distinguish new starts, total students and university targets','以官方2026規劃量、Adelaide個案及10月30日政策回應重新檢視招生壓力；空餘規劃名額不等於個人錄取或簽證保證。','A recheck connects the official 2026 planning level, Adelaide’s experience and the October 30 policy response without equating unused allocations with an individual admission or visa guarantee.',[
('澳洲2026年新海外學生入學規劃量為29.5萬，但這個數字不能直接當成實際入學人數。教育部公立大學指標名額文件記載，政府於2025年8月4日公布2026規劃安排。文件描述的是新海外學生入學與機構分配，不是所有國際在校生，也不是每所學校一定招滿的承諾。本次修訂移除原稿將規劃工具直接稱作招生上限的簡化，重新區分不同統計口徑。','The official 2026 National Planning Level is 295,000 new overseas student commencements. The education department’s public-university allocation factsheet dates the announcement to August 4, 2025. It concerns new starts and institutional allocations, not all international students or guaranteed enrolments. This revision removes the earlier shorthand equating the planning instrument with a straightforward admissions cap.'),
('指標名額提供機構規劃的框架，實際招生仍要經過學生選擇、學校錄取、簽證及到校等環節。教育部文件另說明額外分配、住宿與東南亞合作等考量，顯示名額安排有政策目的，而不是只按申請人數自動分配。對家庭而言，從學校尚有規劃空間，無法推出自己申請的科系有空位，也無法推出政府會核准簽證；這些問題需要不同單位的正式答覆。','Allocations support planning, while recruitment still depends on student choice, admission, visas and arrival. The factsheet describes additional allocations and considerations including housing and Southeast Asian engagement. Available institutional planning space therefore does not establish a vacancy in a particular degree or a favourable visa decision. Families need separate answers from the relevant decision-makers.'),
('ABC於9月25日報導Adelaide University個案，列出2026年國際學生總數16,677人，對照前身兩校前一年同期合計20,820人。這是整體學生人數比較，不是新海外學生入學名額使用率。報導所稱第一學期比目標低約四成，也指校方招生目標，不能改寫成政府配額只使用六成。合併新校的轉型背景同樣重要，單一個案不能代表每所澳洲大學的情況。','ABC’s September 25 Adelaide University report compares 16,677 international students with 20,820 at its predecessors a year earlier. These are total student counts, not allocation-use rates. Its reported first-semester shortfall of about 40% concerns the university’s target, not a statement that 60% of a government allocation was used. The merged institution’s transition also limits national generalization.'),
('10月30日，國際教育助理部長Julian Hill在正式演說承認，政策調整、全球競爭與生活成本共同影響招生，並提出南亞財力標準與相關簽證作業的檢討方向。演說說明11月將諮詢業者，也提及其他國家的資金存入制度作為較長期構想。這些是政策討論與後續安排，不能寫成澳洲已實施新的保證金制度，更不能自行替台灣學生設定尚未公布的財力門檻。','In his October 30 speech, Julian Hill acknowledged policy changes, competition and living costs, and outlined review of South Asian financial-capacity settings. November consultation and an interest in other countries’ deposited-funds approaches were prospective steps. They do not establish an implemented Australian deposit scheme or a newly announced financial threshold for Taiwanese students.'),
('ABC同日的獨立報導將政府回應放在大學收入與拒簽壓力的背景中，提醒招生不足不只是名額多寡的問題。媒體引用的未來收入損失與新生下降預估，仍屬預測，不能與已結算的年度財報混用。編輯分析認為，閱讀此類新聞時應先圈出時間、對象與衡量單位，再比較不同來源；只有先確認它們談的是同一群學生，數字之間的差距才具有可解釋的意義。','ABC’s October 30 independent coverage places the response alongside university revenue and refusal pressures. Forecast losses and projected declines are not completed annual financial results. Our editorial reading method is to identify the period, population and unit before comparing reports. A numerical gap becomes interpretable only when the sources describe comparable groups.'),
('對台灣申請人，最實際的做法是把選校理由與市場消息分開保存。課程是否符合學習目標、學費與生活費能否負擔、校方提供哪些支持，應有具體證據；國際招生放緩則是另一個需要追蹤的背景。若某校積極招募，並不表示所有入學條件都會下降；若有獎學金宣傳，也應核對該年度、科系與續領條件，而不是因為新聞說有空額就預期自動獲得優惠。','Taiwanese applicants should keep course fit, affordability and student support separate from market headlines. Slower recruitment is relevant context, but active marketing does not establish lower admission standards. Scholarship offers require checks of intake, programme and renewal conditions; reported spare capacity does not mean a discount will automatically follow.'),
('已在規劃出發的家庭，可以要求學校用書面確認錄取條件、開課日期與延期安排，再按官方程序處理簽證。把規劃量當成個人保障，容易過早支付不可退費的支出；把單一大學下滑當成整個國家教育品質下降，也同樣超過證據。本文不替任何大學判定財務安全，亦不以招生數字預測個人畢業或就業結果。需要比較的是具體課程與可履行的服務，而不是只有國家總量。','Before travel, obtain written confirmation of offer conditions, start dates and deferral arrangements and follow the official visa process. Treating planning space as a personal guarantee can encourage premature non-refundable spending. Treating one university’s decline as proof of national educational deterioration is equally unsupported. We assess neither institutional financial safety nor an individual’s graduation or employment prospects from recruitment counts.'),
('後續應追蹤教育部同口徑入學統計、正式政策文件與各校已公布財報，並保留修訂日期。尤其11月政策諮詢與實際立法之間仍有距離，報導不能用「準備檢討」代替「已生效」。這次補寫以Adelaide的外部報導說明統計差別，而非替原文未查清的全國比例補上猜測。配圖為墨爾本大學Old Arts Building授權資料照，並非Adelaide校園，也不是當日招生或政策活動的現場照片。','Follow comparable official enrolment data, enacted policy documents and published university accounts, retaining their revision dates. November consultation should not be reported as effective legislation. The Adelaide reporting illustrates measurement differences rather than supplying an invented national ratio. The licensed image depicts Melbourne’s Old Arts Building, not Adelaide or the policy event.')],
[('Department of Education — 2026 indicative public-university allocations','https://www.education.gov.au/download/19711/factsheet-indicative-allocations-publicly-funded-university-new-overseas-student-commencements-2026/42976/document/pdf'),('ABC — Adelaide international-student targets, September 25','https://www.abc.net.au/news/2026-09-25/adelaide-university-off-international-student-targets/107190580'),('Julian Hill — official October 30 speech','https://ministers.education.gov.au/hill/2026-annual-conference-future-thinking-international-education-association-australia'),('ABC — independent October 30 policy coverage','https://www.abc.net.au/news/2026-10-30/labor-moves-to-fix-student-visa-crackdown/107325422')],
dict(image='/images/share-photos/0cf2f06a284b6a4248c6830d.jpg',imageAlt='墨爾本大學Old Arts Building資料照，非Adelaide校園',imageCredit='Polly clip / CC BY-SA 3.0；原圖裁切版本',imageSource='https://commons.wikimedia.org/wiki/File:Old_Arts_Building._Parkville_Campus_of_University_of_Melbourne_(cropped).JPG'),
dict(newsValue='補上9月Adelaide個案與10月底政策回應，修正將規劃量當硬性招生上限或錄取保證的簡化。',background='說明2025公布2026規劃安排，區分新海外入學、國際在校總人數、校方目標與政府分配。',development='對照ABC校園個案與10月30日官方演說，將11月諮詢和長期存款構想與已生效規定分開。',perspectives='以政府文件與ABC獨立採訪並列，保留機構收入壓力和政策品質目標，不把預估當結算實績。',taiwanImpact='從台灣申請者角度整理課程、支出、獎學金與開課確認，避免空餘規劃量被誤用為個人保證。',uncertainty='不從合併大學個案推出全國比例，不判定任何大學財務安全，也不預測學生簽證與就業結果。',independence='ABC是獨立公共媒體，有校方數據及訪談背景，非教育部公告鏡像；兩次報導日期與用途明確區分。'))

for z,e in [('美國賓州州立大學Old Main資料照，非本案聽證現場','Penn State Old Main archive photograph, not the court hearing'),('伯明罕城市大學校園資料照，不代表合規處分','Birmingham City University archive photograph; no compliance sanction implied'),('墨爾本大學Old Arts Building資料照，非Adelaide校園','University of Melbourne Old Arts Building archive photograph, not Adelaide'),('Penn State iGEM 2008 / Public domain；資料照','Penn State iGEM 2008 / Public domain; archive photograph'),('N Chadwick / CC BY-SA 2.0；資料照','N Chadwick / CC BY-SA 2.0; archive photograph'),('Polly clip / CC BY-SA 3.0；原圖裁切版本','Polly clip / CC BY-SA 3.0; cropped source version')]:over[z]=e
for path,obj in [('src/data/i18n/en-overrides.json',over),('docs/editorial/news-reviews.json',reviews),(f'docs/daily-checks/{D}/archive-prepared.json',items)]:
 (R/path).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
